/* ================= GUIDE (onglet du menu, v1.15) =================
   Le « codex » du jeu : rubriques courtes et dépliables (<details>), lisibles au téléphone en paysage
   comme au bureau. Textes statiques (aucune donnée extérieure) dans les 9 langues ; la rubrique des
   raccourcis est GÉNÉRÉE depuis les touches réellement attribuées (SETTINGS.keys, 01-settings.js).
   Les chiffres cités sont ceux du code (04-data, 08-actions, 10-simulation, 11-cataclysm) : à tenir à
   jour si l'équilibrage change. */
const GUIDE = {
fr:{ title:"GUIDE DE LA DERNIÈRE BATAILLE", intro:"Tout ce qu'il faut savoir, en bref. Touchez une rubrique pour la déplier.",
  keysHead:"⌨ Raccourcis & gestes", keysNote:"Toutes les touches se changent dans PARAMÈTRES.",
  gestures:[["Clic droit / appui long au sol","⚑ ordre de position"],["Molette · glisser","faire défiler le champ de bataille"],["Ctrl + molette · pincer","zoomer"],["Maj + clic · Maj + glisser","une seule unité · lasso"],["F8","mesure des performances"]],
  s:[
["🎯 Le but", `<p>Détruisez la <b>base ennemie</b>, à l'autre bout de la carte, avant qu'elle ne détruise la vôtre.</p><ul><li>Une base qui tombe pour la première fois <b>renaît</b> plus solide (×2,2 PV) : il faut l'abattre deux fois.</li><li>La toute première base abattue déclenche la <b>Bombe H</b> : unités et bâtiments rasés (pas les bases), puis 6 min d'hiver nucléaire qui ralentit la production.</li><li>Passé 26 min, le monde s'effondre : les deux bases se délabrent de plus en plus vite.</li></ul>`],
["🌾 Les ressources", `<p><b>Humanité</b> : 🌾 nourriture, 🪙 argent, 💧 eau. <b>G·P·T</b> : ⚡ énergie, ◈ données, 💧 eau de refroidissement. Mêmes rôles, autres noms.</p><ul><li>Revenu de base, sans rien faire : +4 🌾/⚡, +2,5 🪙/◈, +0,6 💧 par seconde.</li><li>Ferme (Panneaux) +4 🌾/⚡ · Marché (Serveur) +4 🪙/◈ · Puits +3 💧 par seconde. Chaque niveau ×1,5 ; un bâtiment gardé en vie monte en régime jusqu'à ×3 en 15 min.</li><li>Les lacs donnent de l'eau ; le camp en difficulté produit jusqu'à +90 %.</li><li>À la Transcendance, 🪙/◈ ne sont plus nécessaires.</li></ul>`],
["✦ Expérience & ères", `<p>L'✦ vient toute seule (+2,2/s, davantage avec les fortifications), en tuant, en frappant la base ennemie et en tenant zones et lac central.</p><ul><li>Évoluer ne la dépense pas : atteignez le palier — <b>360, 980, 2 150 puis 4 200 ✦</b> — et touchez ⚡ ÉVOLUER.</li><li>Chaque ère renforce les nouvelles recrues (de ×1,4 jusqu'à ×4,2 en PV et dégâts) mais les rend plus chères.</li><li>À 13 000 ✦, dans la dernière ère : la Transcendance.</li><li>Le pouvoir spécial ✸, lui, coûte de l'✦.</li></ul>`],
["⚔ Les unités", `<ul><li><b>Mêlée</b> : la moins chère, rapide, frappe fort, fragile.</li><li><b>Tank</b> : un mur de PV, lent, peu de dégâts — il encaisse devant.</li><li><b>Tireur</b> : attaque à distance, fragile.</li><li><b>Siège</b> : très longue portée, obus de zone (pas contre les volants), ×1,6 contre bâtiments et bases.</li><li><b>Aérien</b> : vole — la mêlée ne peut pas le toucher.</li><li><b>Soutien</b> : le médic (ou la ruche, qui fabrique aussi des drones) soigne. Un seul, +1 par amélioration.</li></ul><p>⬆ sur une fiche : +15 % de PV et de dégâts pour les recrues suivantes (3 niveaux). Vétérance : +6 % de dégâts à 4, 8 et 12 victimes. Effectif 30 (40 avec 👥 +10), puis 10 recrues en file d'attente.</p>`],
["🏗 Bâtiments & socles", `<p>Touchez un socle pour bâtir. Les 3 socles de votre base se construisent tout de suite ; les 4 du milieu de la carte seulement une fois vos troupes passées par là — une recrue vient finir le chantier (2 à la fois au plus).</p><ul><li>🧱 Muraille (900 PV) · 🗼 Tourelle (tire seule) · Ferme, Marché, Puits.</li><li>Trois niveaux par bâtiment : +30 % de PV, ×1,5 de production.</li><li>🚪 Garnison : 2 tireurs ou artilleurs par tourelle ou muraille, 3 gardes sur les remparts. À l'abri, ils tirent plus loin et survivent aux inondations.</li><li>Touchez votre base : réparer, fortifier (3 niveaux, +800 PV), auto-réparation, garde.</li></ul>`],
["💧 Zones & lacs", `<ul><li><b>3 lacs</b> : on les prend en y gardant plus d'unités que l'adversaire (+40 ✦). Ils versent de l'eau ; le lac central donne aussi les deux autres ressources et de l'✦.</li><li><b>3 zones stratégiques</b> : +0,5 ✦/s chacune. Le camp dont la base est la plus entamée gagne +5 % d'attaque et de défense par zone qui lui manque.</li><li>⭐ <b>Zone bonus</b> : vers la 3e minute, près du centre, pendant 60 s (+1,4 ✦/s).</li><li>Les hauteurs du terrain donnent un peu plus de portée et de dégâts.</li></ul>`],
["★ Le héros & ses postures", `<p>Quand le sceau ★ apparaît (700 🌾/⚡, 700 🪙/◈, 200 💧 — une fois toutes les 10 min), invoquez votre légende : tant qu'elle vit, <b>toute votre armée frappe ×3 et avance ×2</b>. Le Che soigne autour de lui ; la Singularité frappe plus fort.</p><p>Sa posture (bouton voisin, touche J) :</p><ul><li>🛡 <b>Prudent</b> : seconde ligne derrière ses troupes ; sous 35 % de PV il se replie à la base et n'en repart qu'une fois soigné au-delà de 60 % (médecins, ruches). Pour garder le bonus longtemps.</li><li>★ <b>Avec la troupe</b> : au front de l'armée, jamais devant ; il suit vos ordres d'armée.</li><li>⚔ <b>Offensif</b> : fonce devant, traque les ennemis — leur héros d'abord — et ne recule jamais.</li></ul><p>Un ordre donné au héros sélectionné passe avant sa posture.</p>`],
["✸ Les pouvoirs", `<ul><li><b>✸ Pouvoir spécial</b> (Espace) : frappe toutes les unités ennemies — jamais plus de 65 % de leurs PV —, leurs bâtiments et leur base. Coûte 60 ✦ + 40 par ère, se recharge en ~43 s (plus vite si vous perdez).</li><li><b>☠ Dernier recours</b> : votre base sous 20 % de PV — une fois, gratuit : l'ennemi est durement frappé et sonné, vos troupes sont soignées, la base regagne 500 PV.</li><li><b>🏰 Mode siège</b> : dernière ère et héros en vie, le pouvoir devient un siège de 22 s : la base ennemie encaisse +30 %, vos tirs +10 %.</li><li><b>Nom du pouvoir</b> : en escarmouche, Humanité = Soulèvement, G·P·T = Frappe chirurgicale ; en campagne, il porte le nom de l'ère (de « Pluie de pavés » à « Miroirs solaires »). Même touche ✸.</li></ul>`],
["⚡ Les événements", `<ul><li>🔒 <b>Couvre-feu</b> (humains : les machines bouclent les quartiers) et 🔧 <b>Mise à jour forcée</b> (machines), 15 s chacune, dès la 2e minute. La faction touchée ne bouge plus, ne capture rien et épargne les bâtiments, mais riposte à toute unité à sa portée ; soins, tourelles et garnisons continuent.</li><li>🌧 <b>Pluie fertile</b> : 15 s, un effet différent pour chaque camp (le détail s'affiche la première fois).</li><li>📡 <b>Signal renforcé</b> : 15 s, le pouvoir ✸ se recharge plus vite, plus ou moins selon le camp.</li><li>La <b>santé du monde</b> (jauge du haut) baisse avec le temps, les morts et les pouvoirs : tout s'use, et viennent les <b>cataclysmes</b> —</li></ul><ul><li>Pluie d'acide (13 s) : unités et bâtiments perdent des PV.</li><li>Canicule (14 s) : PV perdus et épuisement.</li><li>Inondation (9 s) : les unités au sol se noient ; volants et garnisons survivent.</li><li>Tempête de sable (11 s) : les volants tombent, portée longue −22 %.</li><li>Météorites (14 s) : impacts au hasard, mortels.</li><li>Frappe nucléaire (rare) : rase tout autour de l'impact, sauf les bases.</li></ul>`],
["⚑ Ordres & sélection", `<ul><li>⚔ <b>Charger</b> : l'armée avance et attaque. ✋ <b>Tenir</b> : elle garde sa ligne de front. ↩ <b>Replier</b> : retour près de la base.</li><li><b>Sélection</b> : touchez une unité pour prendre toute sa classe, encore une fois (ou Maj + clic) pour elle seule ; ⬚ Lasso ou Maj + glisser pour un rectangle ; ✖ ou un tap au sol pour tout lâcher. Avec une sélection, les ordres ne valent que pour elle.</li><li>⚑ <b>Ordre de position</b> — clic droit, ou appui long au doigt, sur le terrain : la sélection (ou toute l'armée) va s'y poster en bloc, mêlée devant, tireurs derrière. En chemin elle ne combat que ce qui lui barre la route ; vers l'arrière, elle décroche sans s'arrêter. Arrivée, elle tient le point et riposte à tout ce qui approche, jusqu'au prochain ordre. Le fanion reste planté tant que tous ne sont pas arrivés.</li><li>⚏ <b>Formation</b> : rangement automatique, corps à corps devant, artillerie et soutien derrière.</li></ul>`],
]},
en:{ title:"FIELD GUIDE TO THE LAST BATTLE", intro:"Everything you need to know, in short. Tap a section to open it.",
  keysHead:"⌨ Shortcuts & gestures", keysNote:"Every key can be rebound in SETTINGS.",
  gestures:[["Right-click / long-press on the ground","⚑ position order"],["Wheel · drag","scroll the battlefield"],["Ctrl + wheel · pinch","zoom"],["Shift + click · Shift + drag","a single unit · lasso"],["F8","performance meter"]],
  s:[
["🎯 The goal", `<p>Destroy the <b>enemy base</b>, at the far end of the map, before it destroys yours.</p><ul><li>A base that falls for the first time is <b>reborn</b> stronger (×2.2 HP): you must bring it down twice.</li><li>The very first base to fall triggers the <b>H-bomb</b>: units and buildings razed (not the bases), then 6 min of nuclear winter that slows production.</li><li>After 26 min the world collapses: both bases crumble faster and faster.</li></ul>`],
["🌾 Resources", `<p><b>Humanity</b>: 🌾 food, 🪙 money, 💧 water. <b>G·P·T</b>: ⚡ energy, ◈ data, 💧 cooling water. Same roles, different names.</p><ul><li>Base income, for free: +4 🌾/⚡, +2.5 🪙/◈, +0.6 💧 per second.</li><li>Farm (Solar panels) +4 🌾/⚡ · Market (Server) +4 🪙/◈ · Well +3 💧 per second. Each level ×1.5; a building kept alive ramps up to ×3 over 15 min.</li><li>Lakes give water; the side in trouble produces up to +90%.</li><li>At Transcendence, 🪙/◈ are no longer needed.</li></ul>`],
["✦ Experience & eras", `<p>✦ comes on its own (+2.2/s, more with fortifications), from kills, from hitting the enemy base and from holding zones and the central lake.</p><ul><li>Evolving does not spend it: reach the threshold — <b>360, 980, 2,150 then 4,200 ✦</b> — and tap ⚡ EVOLVE.</li><li>Each era strengthens new recruits (from ×1.4 up to ×4.2 HP and damage) but makes them dearer.</li><li>At 13,000 ✦ in the last era: Transcendence.</li><li>The special power ✸, however, costs ✦.</li></ul>`],
["⚔ Units", `<ul><li><b>Melee</b>: cheapest, fast, hits hard, fragile.</li><li><b>Tank</b>: a wall of HP, slow, low damage — it soaks up hits in front.</li><li><b>Shooter</b>: ranged attack, fragile.</li><li><b>Siege</b>: very long range, area shells (not against flyers), ×1.6 against buildings and bases.</li><li><b>Air</b>: flies — melee cannot touch it.</li><li><b>Support</b>: the medic (or the hive, which also builds drones) heals. Only one, +1 per upgrade.</li></ul><p>⬆ on a card: +15% HP and damage for the next recruits (3 levels). Veterancy: +6% damage at 4, 8 and 12 kills. Army size 30 (40 with 👥 +10), then 10 recruits wait in a queue.</p>`],
["🏗 Buildings & plots", `<p>Tap a plot to build. Your base's 3 plots build instantly; the 4 in mid-map only once your troops have passed there — a recruit walks over to finish the site (2 at a time at most).</p><ul><li>🧱 Wall (900 HP) · 🗼 Turret (shoots on its own) · Farm, Market, Well.</li><li>Three levels per building: +30% HP, ×1.5 production.</li><li>🚪 Garrison: 2 shooters or gunners per turret or wall, 3 guards on the ramparts. Under cover they shoot farther and survive floods.</li><li>Tap your base: repair, fortify (3 levels, +800 HP), auto-repair, guard.</li></ul>`],
["💧 Zones & lakes", `<ul><li><b>3 lakes</b>: taken by keeping more units there than the opponent (+40 ✦). They provide water; the central lake also gives the other two resources and ✦.</li><li><b>3 strategic zones</b>: +0.5 ✦/s each. The side whose base is more damaged gets +5% attack and defence per zone it lacks.</li><li>⭐ <b>Bonus zone</b>: around minute 3, near the centre, for 60 s (+1.4 ✦/s).</li><li>High ground gives a little more range and damage.</li></ul>`],
["★ The hero & stances", `<p>When the ★ seal appears (700 🌾/⚡, 700 🪙/◈, 200 💧 — once every 10 min), summon your legend: while it lives, <b>your whole army hits ×3 and moves ×2</b>. Che heals those around him; the Singularity hits harder.</p><p>Its stance (button next to it, key J):</p><ul><li>🛡 <b>Cautious</b>: second line behind its troops; under 35% HP it falls back to the base and only leaves once healed above 60% (medics, hives). To keep the bonus going.</li><li>★ <b>With the troops</b>: at the army's front, never ahead; it follows your army orders.</li><li>⚔ <b>Aggressive</b>: rushes ahead, hunts enemies — their hero first — and never retreats.</li></ul><p>An order given to the selected hero overrides its stance.</p>`],
["✸ Powers", `<ul><li><b>✸ Special power</b> (Space): hits every enemy unit — never more than 65% of its HP —, their buildings and base. Costs 60 ✦ + 40 per era, recharges in ~43 s (faster when losing).</li><li><b>☠ Last resort</b>: your base under 20% HP — once, free: the enemy is hit hard and stunned, your troops are healed, the base regains 500 HP.</li><li><b>🏰 Siege mode</b>: last era with the hero alive, the power becomes a 22 s siege: the enemy base takes +30%, your ranged fire +10%.</li><li><b>Power names</b>: in skirmish, Humanity = Uprising, G·P·T = Surgical strike; in the campaign, the power is named after the era (from “Cobblestone Rain” to “Solar Mirrors”). Same ✸ key.</li></ul>`],
["⚡ Events", `<ul><li>🔒 <b>Curfew</b> (humans: the machines seal off the neighbourhoods) and 🔧 <b>Forced update</b> (machines), 15 s each, from minute 2. The affected faction stops moving, captures nothing and spares buildings, but fights back against any unit in range; healing, turrets and garrisons carry on.</li><li>🌧 <b>Fertile rain</b>: 15 s, a different effect for each side (details shown the first time it happens).</li><li>📡 <b>Boosted signal</b>: 15 s, the ✸ power recharges faster, by a different amount for each side.</li><li><b>World health</b> (top gauge) drops with time, deaths and powers: everything wears down, and <b>cataclysms</b> come —</li></ul><ul><li>Acid rain (13 s): units and buildings lose HP.</li><li>Heatwave (14 s): HP loss and exhaustion.</li><li>Flood (9 s): ground units drown; flyers and garrisons survive.</li><li>Sandstorm (11 s): flyers fall, long range −22%.</li><li>Meteors (14 s): random, deadly impacts.</li><li>Nuclear strike (rare): razes everything around the impact, except bases.</li></ul>`],
["⚑ Orders & selection", `<ul><li>⚔ <b>Charge</b>: the army advances and attacks. ✋ <b>Hold</b>: it keeps its front line. ↩ <b>Retreat</b>: back near the base.</li><li><b>Selection</b>: tap a unit to take its whole class, tap again (or Shift + click) for that one alone; ⬚ Lasso or Shift + drag for a rectangle; ✖ or a tap on the ground to let go. With a selection, orders only apply to it.</li><li>⚑ <b>Position order</b> — right-click, or long-press with a finger, on the ground: the selection (or the whole army) goes to stand there in a block, melee in front, shooters behind. On the way it only fights what blocks its path; moving back, it disengages without stopping. Once there it holds the spot and fights back against anything that comes close, until the next order. The flag stays planted until everyone has arrived.</li><li>⚏ <b>Formation</b>: automatic ranks, melee in front, artillery and support behind.</li></ul>`],
]},
es:{ title:"GUÍA DE LA ÚLTIMA BATALLA", intro:"Todo lo que hay que saber, en breve. Toca un apartado para desplegarlo.",
  keysHead:"⌨ Atajos y gestos", keysNote:"Todas las teclas se cambian en AJUSTES.",
  gestures:[["Clic derecho / pulsación larga en el suelo","⚑ orden de posición"],["Rueda · arrastrar","desplazar el campo de batalla"],["Ctrl + rueda · pellizcar","zoom"],["Mayús + clic · Mayús + arrastrar","una sola unidad · lazo"],["F8","medidor de rendimiento"]],
  s:[
["🎯 El objetivo", `<p>Destruye la <b>base enemiga</b>, al otro extremo del mapa, antes de que destruya la tuya.</p><ul><li>Una base que cae por primera vez <b>renace</b> más fuerte (×2,2 PV): hay que derribarla dos veces.</li><li>La primera base derribada desata la <b>Bomba H</b>: unidades y edificios arrasados (no las bases) y 6 min de invierno nuclear que frena la producción.</li><li>Pasados 26 min el mundo se derrumba: ambas bases se deterioran cada vez más rápido.</li></ul>`],
["🌾 Recursos", `<p><b>Humanidad</b>: 🌾 comida, 🪙 dinero, 💧 agua. <b>G·P·T</b>: ⚡ energía, ◈ datos, 💧 agua de refrigeración. Mismos papeles, otros nombres.</p><ul><li>Ingreso base, sin hacer nada: +4 🌾/⚡, +2,5 🪙/◈, +0,6 💧 por segundo.</li><li>Granja (Paneles) +4 🌾/⚡ · Mercado (Servidor) +4 🪙/◈ · Pozo +3 💧 por segundo. Cada nivel ×1,5; un edificio que sobrevive rinde hasta ×3 en 15 min.</li><li>Los lagos dan agua; el bando en apuros produce hasta un +90 %.</li><li>Con la Trascendencia, 🪙/◈ dejan de ser necesarios.</li></ul>`],
["✦ Experiencia y eras", `<p>La ✦ llega sola (+2,2/s, más con fortificaciones), al matar, al golpear la base enemiga y al controlar zonas y el lago central.</p><ul><li>Evolucionar no la gasta: alcanza el umbral — <b>360, 980, 2150 y 4200 ✦</b> — y toca ⚡ EVOLUCIONAR.</li><li>Cada era refuerza a los nuevos reclutas (de ×1,4 hasta ×4,2 en PV y daño) pero los encarece.</li><li>Con 13 000 ✦ en la última era: la Trascendencia.</li><li>El poder especial ✸, en cambio, cuesta ✦.</li></ul>`],
["⚔ Las unidades", `<ul><li><b>Cuerpo a cuerpo</b>: la más barata, rápida, pega fuerte, frágil.</li><li><b>Tanque</b>: un muro de PV, lento, poco daño — aguanta delante.</li><li><b>Tirador</b>: ataque a distancia, frágil.</li><li><b>Asedio</b>: alcance muy largo, proyectiles de área (no contra voladores), ×1,6 contra edificios y bases.</li><li><b>Aéreo</b>: vuela — el cuerpo a cuerpo no puede tocarlo.</li><li><b>Apoyo</b>: el médico (o la colmena, que además fabrica drones) cura. Solo uno, +1 por mejora.</li></ul><p>⬆ en una ficha: +15 % de PV y daño para los siguientes reclutas (3 niveles). Veteranía: +6 % de daño a las 4, 8 y 12 bajas. Efectivo 30 (40 con 👥 +10); luego 10 reclutas esperan en cola.</p>`],
["🏗 Edificios y solares", `<p>Toca un solar para construir. Los 3 de tu base se construyen al instante; los 4 del centro del mapa solo cuando tus tropas han pasado por allí — un recluta va a terminar la obra (2 a la vez como máximo).</p><ul><li>🧱 Muralla (900 PV) · 🗼 Torreta (dispara sola) · Granja, Mercado, Pozo.</li><li>Tres niveles por edificio: +30 % de PV, ×1,5 de producción.</li><li>🚪 Guarnición: 2 tiradores o artilleros por torreta o muralla, 3 guardias en las almenas. A cubierto disparan más lejos y sobreviven a las inundaciones.</li><li>Toca tu base: reparar, fortificar (3 niveles, +800 PV), autorreparación, guardia.</li></ul>`],
["💧 Zonas y lagos", `<ul><li><b>3 lagos</b>: se toman manteniendo allí más unidades que el rival (+40 ✦). Dan agua; el lago central da además los otros dos recursos y ✦.</li><li><b>3 zonas estratégicas</b>: +0,5 ✦/s cada una. El bando con la base más dañada gana +5 % de ataque y defensa por cada zona que le falta.</li><li>⭐ <b>Zona bonus</b>: hacia el minuto 3, cerca del centro, durante 60 s (+1,4 ✦/s).</li><li>Las alturas del terreno dan algo más de alcance y daño.</li></ul>`],
["★ El héroe y sus posturas", `<p>Cuando aparece el sello ★ (700 🌾/⚡, 700 🪙/◈, 200 💧 — una vez cada 10 min), invoca a tu leyenda: mientras viva, <b>todo tu ejército golpea ×3 y avanza ×2</b>. El Che cura a su alrededor; la Singularidad golpea más fuerte.</p><p>Su postura (botón contiguo, tecla J):</p><ul><li>🛡 <b>Prudente</b>: segunda línea tras sus tropas; con menos del 35 % de vida se repliega a la base y solo sale cuando se cura por encima del 60 % (médicos, colmenas). Para conservar la bonificación.</li><li>★ <b>Con la tropa</b>: en el frente del ejército, nunca delante; sigue tus órdenes de ejército.</li><li>⚔ <b>Ofensivo</b>: se lanza delante, caza enemigos —primero a su héroe— y nunca retrocede.</li></ul><p>Una orden dada al héroe seleccionado prima sobre su postura.</p>`],
["✸ Los poderes", `<ul><li><b>✸ Poder especial</b> (Espacio): golpea a todas las unidades enemigas —nunca más del 65 % de su vida—, sus edificios y su base. Cuesta 60 ✦ + 40 por era y se recarga en ~43 s (más rápido si vas perdiendo).</li><li><b>☠ Último recurso</b>: tu base por debajo del 20 % — una vez, gratis: el enemigo recibe un golpe duro y queda aturdido, tus tropas se curan y la base recupera 500 PV.</li><li><b>🏰 Modo asedio</b>: en la última era con el héroe vivo, el poder se convierte en un asedio de 22 s: la base enemiga recibe +30 %, tus disparos +10 %.</li><li><b>Nombres del poder</b>: en escaramuza, Humanidad = Levantamiento, G·P·T = Ataque quirúrgico; en la campaña lleva el nombre de la era (de «Lluvia de adoquines» a «Espejos solares»). Misma tecla ✸.</li></ul>`],
["⚡ Los eventos", `<ul><li>🔒 <b>Toque de queda</b> (humanos: las máquinas acordonan los barrios) y 🔧 <b>Actualización forzada</b> (máquinas), 15 s cada una, desde el minuto 2. El bando afectado deja de moverse, no captura nada y no ataca edificios, pero responde a toda unidad a su alcance; curas, torretas y guarniciones siguen.</li><li>🌧 <b>Lluvia fértil</b>: 15 s, un efecto distinto para cada bando (el detalle aparece la primera vez).</li><li>📡 <b>Señal reforzada</b>: 15 s, el poder ✸ se recarga más rápido, en distinta medida según el bando.</li><li>La <b>salud del mundo</b> (barra superior) baja con el tiempo, las muertes y los poderes: todo se desgasta y llegan los <b>cataclismos</b> —</li></ul><ul><li>Lluvia ácida (13 s): unidades y edificios pierden vida.</li><li>Ola de calor (14 s): pérdida de vida y agotamiento.</li><li>Inundación (9 s): las unidades terrestres se ahogan; voladores y guarniciones sobreviven.</li><li>Tormenta de arena (11 s): caen los voladores, alcance largo −22 %.</li><li>Meteoritos (14 s): impactos al azar, mortales.</li><li>Ataque nuclear (raro): arrasa todo alrededor del impacto, salvo las bases.</li></ul>`],
["⚑ Órdenes y selección", `<ul><li>⚔ <b>Cargar</b>: el ejército avanza y ataca. ✋ <b>Mantener</b>: conserva su línea de frente. ↩ <b>Replegar</b>: vuelve cerca de la base.</li><li><b>Selección</b>: toca una unidad para tomar toda su clase, otra vez (o Mayús + clic) para ella sola; ⬚ Lazo o Mayús + arrastrar para un rectángulo; ✖ o un toque en el suelo para soltarla. Con selección, las órdenes solo valen para ella.</li><li>⚑ <b>Orden de posición</b> — clic derecho, o pulsación larga con el dedo, en el terreno: la selección (o todo el ejército) va a apostarse allí en bloque, cuerpo a cuerpo delante, tiradores detrás. Por el camino solo combate lo que le cierra el paso; hacia atrás, se retira sin detenerse. Al llegar, mantiene el punto y responde a todo lo que se acerque, hasta la siguiente orden. La bandera sigue clavada hasta que todos han llegado.</li><li>⚏ <b>Formación</b>: orden automático, cuerpo a cuerpo delante, artillería y apoyo detrás.</li></ul>`],
]},
de:{ title:"HANDBUCH ZUR LETZTEN SCHLACHT", intro:"Alles Wichtige in Kürze. Tippe auf einen Abschnitt, um ihn aufzuklappen.",
  keysHead:"⌨ Tasten & Gesten", keysNote:"Jede Taste lässt sich in EINSTELLUNGEN ändern.",
  gestures:[["Rechtsklick / langes Drücken auf den Boden","⚑ Positionsbefehl"],["Mausrad · Ziehen","Schlachtfeld scrollen"],["Strg + Mausrad · Kneifen","Zoom"],["Umschalt + Klick · Umschalt + Ziehen","eine einzelne Einheit · Lasso"],["F8","Leistungsanzeige"]],
  s:[
["🎯 Das Ziel", `<p>Zerstöre die <b>feindliche Basis</b> am anderen Ende der Karte, bevor sie deine zerstört.</p><ul><li>Eine Basis, die zum ersten Mal fällt, <b>ersteht</b> stärker wieder auf (×2,2 LP): Man muss sie zweimal niederringen.</li><li>Die allererste gefallene Basis löst die <b>H-Bombe</b> aus: Einheiten und Gebäude vernichtet (nicht die Basen), danach 6 Min. nuklearer Winter mit gebremster Produktion.</li><li>Nach 26 Min. bricht die Welt zusammen: Beide Basen verfallen immer schneller.</li></ul>`],
["🌾 Ressourcen", `<p><b>Menschheit</b>: 🌾 Nahrung, 🪙 Geld, 💧 Wasser. <b>G·P·T</b>: ⚡ Energie, ◈ Daten, 💧 Kühlwasser. Gleiche Rollen, andere Namen.</p><ul><li>Grundeinkommen, ganz von selbst: +4 🌾/⚡, +2,5 🪙/◈, +0,6 💧 pro Sekunde.</li><li>Farm (Solarpaneele) +4 🌾/⚡ · Markt (Server) +4 🪙/◈ · Brunnen +3 💧 pro Sekunde. Jede Stufe ×1,5; ein überlebendes Gebäude steigert sich in 15 Min. bis ×3.</li><li>Seen liefern Wasser; die bedrängte Seite produziert bis zu +90 %.</li><li>Mit der Transzendenz wird 🪙/◈ überflüssig.</li></ul>`],
["✦ Erfahrung & Zeitalter", `<p>✦ kommt von selbst (+2,2/s, mehr mit Befestigungen), durch Siege, Treffer auf die feindliche Basis und das Halten von Zonen und dem mittleren See.</p><ul><li>Entwickeln verbraucht sie nicht: Erreiche die Schwelle — <b>360, 980, 2150, dann 4200 ✦</b> — und tippe auf ⚡ ENTWICKELN.</li><li>Jedes Zeitalter stärkt neue Rekruten (von ×1,4 bis ×4,2 LP und Schaden), macht sie aber teurer.</li><li>Bei 13 000 ✦ im letzten Zeitalter: die Transzendenz.</li><li>Die Spezialfähigkeit ✸ dagegen kostet ✦.</li></ul>`],
["⚔ Die Einheiten", `<ul><li><b>Nahkampf</b>: am billigsten, schnell, schlägt hart zu, zerbrechlich.</li><li><b>Panzer</b>: eine LP-Mauer, langsam, wenig Schaden — steckt vorne ein.</li><li><b>Schütze</b>: Fernangriff, zerbrechlich.</li><li><b>Belagerung</b>: sehr große Reichweite, Flächengeschosse (nicht gegen Flieger), ×1,6 gegen Gebäude und Basen.</li><li><b>Luft</b>: fliegt — Nahkampf erreicht sie nicht.</li><li><b>Unterstützung</b>: der Sanitäter (oder der Schwarm, der auch Drohnen baut) heilt. Nur einer, +1 pro Verbesserung.</li></ul><p>⬆ auf einer Karte: +15 % LP und Schaden für die nächsten Rekruten (3 Stufen). Veteranen: +6 % Schaden bei 4, 8 und 12 Siegen. Truppenstärke 30 (40 mit 👥 +10), danach warten 10 Rekruten in der Schlange.</p>`],
["🏗 Gebäude & Bauplätze", `<p>Tippe auf einen Bauplatz, um zu bauen. Die 3 Plätze deiner Basis entstehen sofort; die 4 in der Kartenmitte erst, wenn deine Truppen dort waren — ein Rekrut stellt die Baustelle fertig (höchstens 2 gleichzeitig).</p><ul><li>🧱 Mauer (900 LP) · 🗼 Turm (schießt selbst) · Farm, Markt, Brunnen.</li><li>Drei Stufen pro Gebäude: +30 % LP, ×1,5 Produktion.</li><li>🚪 Garnison: 2 Schützen oder Artilleristen pro Turm oder Mauer, 3 Wachen auf den Zinnen. In Deckung schießen sie weiter und überstehen Fluten.</li><li>Tippe auf deine Basis: reparieren, befestigen (3 Stufen, +800 LP), Selbstreparatur, Wache.</li></ul>`],
["💧 Zonen & Seen", `<ul><li><b>3 Seen</b>: erobert, indem man dort mehr Einheiten hält als der Gegner (+40 ✦). Sie liefern Wasser; der mittlere See auch die beiden anderen Ressourcen und ✦.</li><li><b>3 strategische Zonen</b>: je +0,5 ✦/s. Die Seite mit der stärker beschädigten Basis erhält +5 % Angriff und Verteidigung pro fehlender Zone.</li><li>⭐ <b>Bonuszone</b>: gegen Minute 3, nahe der Mitte, 60 s lang (+1,4 ✦/s).</li><li>Anhöhen geben etwas mehr Reichweite und Schaden.</li></ul>`],
["★ Der Held & seine Haltungen", `<p>Erscheint das Siegel ★ (700 🌾/⚡, 700 🪙/◈, 200 💧 — einmal alle 10 Min.), beschwöre deine Legende: Solange sie lebt, <b>schlägt deine ganze Armee ×3 zu und bewegt sich ×2</b>. Che heilt in seiner Nähe; die Singularität schlägt härter zu.</p><p>Seine Haltung (Knopf daneben, Taste J):</p><ul><li>🛡 <b>Vorsichtig</b>: zweite Reihe hinter seinen Truppen; unter 35 % LP zieht er sich zur Basis zurück und verlässt sie erst, wenn er über 60 % geheilt ist (Sanitäter, Bienenstöcke). So bleibt der Bonus lange erhalten.</li><li>★ <b>Mit der Truppe</b>: an der Front der Armee, nie davor; er folgt deinen Armeebefehlen.</li><li>⚔ <b>Offensiv</b>: stürmt voraus, jagt Feinde — zuerst ihren Helden — und weicht nie zurück.</li></ul><p>Ein Befehl an den ausgewählten Helden geht seiner Haltung vor.</p>`],
["✸ Die Fähigkeiten", `<ul><li><b>✸ Spezialfähigkeit</b> (Leertaste): trifft alle feindlichen Einheiten — nie mehr als 65 % ihrer LP —, ihre Gebäude und ihre Basis. Kostet 60 ✦ + 40 pro Zeitalter, lädt in ~43 s (schneller, wenn du verlierst).</li><li><b>☠ Letzter Ausweg</b>: deine Basis unter 20 % LP — einmalig, kostenlos: Der Feind wird hart getroffen und betäubt, deine Truppen geheilt, die Basis erhält 500 LP.</li><li><b>🏰 Belagerungsmodus</b>: im letzten Zeitalter mit lebendem Helden wird die Fähigkeit zu einer 22-s-Belagerung: Die feindliche Basis nimmt +30 %, dein Fernkampf +10 %.</li><li><b>Namen der Fähigkeit</b>: im Gefecht Menschheit = Aufstand, G·P·T = Chirurgischer Schlag; in der Kampagne trägt sie den Namen des Zeitalters (von „Pflastersteinregen“ bis „Sonnenspiegel“). Gleiche Taste ✸.</li></ul>`],
["⚡ Die Ereignisse", `<ul><li>🔒 <b>Ausgangssperre</b> (Menschen: die Maschinen riegeln die Viertel ab) und 🔧 <b>Erzwungenes Update</b> (Maschinen), je 15 s, ab Minute 2. Die betroffene Fraktion bewegt sich nicht mehr, erobert nichts und verschont Gebäude, wehrt sich aber gegen jede Einheit in Reichweite; Heilung, Türme und Garnisonen arbeiten weiter.</li><li>🌧 <b>Fruchtbarer Regen</b>: 15 s, für jede Seite ein anderer Effekt (Details beim ersten Auftreten).</li><li>📡 <b>Verstärktes Signal</b>: 15 s, die Fähigkeit ✸ lädt schneller, je nach Seite unterschiedlich stark.</li><li>Die <b>Weltgesundheit</b> (Leiste oben) sinkt mit der Zeit, den Toten und den Fähigkeiten: Alles verschleißt, und es kommen die <b>Katastrophen</b> —</li></ul><ul><li>Saurer Regen (13 s): Einheiten und Gebäude verlieren LP.</li><li>Hitzewelle (14 s): LP-Verlust und Erschöpfung.</li><li>Flut (9 s): Bodeneinheiten ertrinken; Flieger und Garnisonen überleben.</li><li>Sandsturm (11 s): Flieger stürzen ab, Fernkampf −22 % Reichweite.</li><li>Meteoriten (14 s): zufällige, tödliche Einschläge.</li><li>Atomschlag (selten): löscht alles rund um den Einschlag aus, außer den Basen.</li></ul>`],
["⚑ Befehle & Auswahl", `<ul><li>⚔ <b>Angreifen</b>: Die Armee rückt vor und greift an. ✋ <b>Halten</b>: Sie hält ihre Frontlinie. ↩ <b>Rückzug</b>: zurück in die Nähe der Basis.</li><li><b>Auswahl</b>: Tippe auf eine Einheit, um ihre ganze Klasse zu wählen, erneut (oder Umschalt + Klick) für sie allein; ⬚ Lasso oder Umschalt + Ziehen für ein Rechteck; ✖ oder ein Tipp auf den Boden zum Abwählen. Mit Auswahl gelten Befehle nur für sie.</li><li>⚑ <b>Positionsbefehl</b> — Rechtsklick oder langes Drücken mit dem Finger auf das Gelände: Die Auswahl (oder die ganze Armee) stellt sich dort als Block auf, Nahkampf vorne, Schützen dahinter. Unterwegs kämpft sie nur gegen das, was ihr den Weg versperrt; nach hinten löst sie sich, ohne anzuhalten. Dort angekommen hält sie den Punkt und wehrt sich gegen alles, was naht — bis zum nächsten Befehl. Die Fahne bleibt stehen, bis alle angekommen sind.</li><li>⚏ <b>Formation</b>: automatische Reihen, Nahkampf vorne, Artillerie und Unterstützung hinten.</li></ul>`],
]},
it:{ title:"GUIDA ALL'ULTIMA BATTAGLIA", intro:"Tutto quello che serve sapere, in breve. Tocca una sezione per aprirla.",
  keysHead:"⌨ Scorciatoie e gesti", keysNote:"Tutti i tasti si cambiano in IMPOSTAZIONI.",
  gestures:[["Clic destro / pressione lunga sul terreno","⚑ ordine di posizione"],["Rotellina · trascinare","scorrere il campo di battaglia"],["Ctrl + rotellina · pizzicare","zoom"],["Maiusc + clic · Maiusc + trascinare","una sola unità · lazo"],["F8","misura delle prestazioni"]],
  s:[
["🎯 L'obiettivo", `<p>Distruggi la <b>base nemica</b>, all'altro capo della mappa, prima che distrugga la tua.</p><ul><li>Una base che cade per la prima volta <b>rinasce</b> più forte (×2,2 PV): va abbattuta due volte.</li><li>La primissima base abbattuta scatena la <b>Bomba H</b>: unità ed edifici rasi al suolo (non le basi), poi 6 min di inverno nucleare che rallenta la produzione.</li><li>Dopo 26 min il mondo crolla: entrambe le basi si sgretolano sempre più in fretta.</li></ul>`],
["🌾 Le risorse", `<p><b>Umanità</b>: 🌾 cibo, 🪙 denaro, 💧 acqua. <b>G·P·T</b>: ⚡ energia, ◈ dati, 💧 acqua di raffreddamento. Stessi ruoli, nomi diversi.</p><ul><li>Rendita base, senza fare nulla: +4 🌾/⚡, +2,5 🪙/◈, +0,6 💧 al secondo.</li><li>Fattoria (Pannelli) +4 🌾/⚡ · Mercato (Server) +4 🪙/◈ · Pozzo +3 💧 al secondo. Ogni livello ×1,5; un edificio tenuto in vita sale fino a ×3 in 15 min.</li><li>I laghi danno acqua; lo schieramento in difficoltà produce fino al +90 %.</li><li>Con la Trascendenza, 🪙/◈ non servono più.</li></ul>`],
["✦ Esperienza ed ere", `<p>La ✦ arriva da sola (+2,2/s, di più con le fortificazioni), uccidendo, colpendo la base nemica e tenendo le zone e il lago centrale.</p><ul><li>Evolvere non la consuma: raggiungi la soglia — <b>360, 980, 2150 poi 4200 ✦</b> — e tocca ⚡ EVOLVI.</li><li>Ogni era rafforza le nuove reclute (da ×1,4 fino a ×4,2 di PV e danni) ma le rende più care.</li><li>A 13 000 ✦ nell'ultima era: la Trascendenza.</li><li>Il potere speciale ✸, invece, costa ✦.</li></ul>`],
["⚔ Le unità", `<ul><li><b>Corpo a corpo</b>: la più economica, veloce, colpisce forte, fragile.</li><li><b>Carro</b>: un muro di PV, lento, pochi danni — incassa davanti.</li><li><b>Tiratore</b>: attacco a distanza, fragile.</li><li><b>Assedio</b>: gittata lunghissima, proiettili ad area (non contro i velivoli), ×1,6 contro edifici e basi.</li><li><b>Aereo</b>: vola — il corpo a corpo non può toccarlo.</li><li><b>Supporto</b>: il medico (o l'alveare, che produce anche droni) cura. Uno solo, +1 per potenziamento.</li></ul><p>⬆ su una scheda: +15 % di PV e danni per le reclute successive (3 livelli). Veterani: +6 % di danni a 4, 8 e 12 uccisioni. Effettivi 30 (40 con 👥 +10), poi 10 reclute in coda.</p>`],
["🏗 Edifici e lotti", `<p>Tocca un lotto per costruire. I 3 lotti della tua base si costruiscono subito; i 4 a metà mappa solo dopo che le tue truppe ci sono passate — una recluta va a finire il cantiere (al massimo 2 alla volta).</p><ul><li>🧱 Muro (900 PV) · 🗼 Torretta (spara da sola) · Fattoria, Mercato, Pozzo.</li><li>Tre livelli per edificio: +30 % di PV, ×1,5 di produzione.</li><li>🚪 Guarnigione: 2 tiratori o artiglieri per torretta o muro, 3 guardie sui bastioni. Al riparo sparano più lontano e sopravvivono alle inondazioni.</li><li>Tocca la tua base: riparare, fortificare (3 livelli, +800 PV), autoriparazione, guardia.</li></ul>`],
["💧 Zone e laghi", `<ul><li><b>3 laghi</b>: si prendono tenendoci più unità dell'avversario (+40 ✦). Danno acqua; il lago centrale dà anche le altre due risorse e ✦.</li><li><b>3 zone strategiche</b>: +0,5 ✦/s ciascuna. Lo schieramento con la base più danneggiata guadagna +5 % di attacco e difesa per ogni zona che gli manca.</li><li>⭐ <b>Zona bonus</b>: verso il 3° minuto, vicino al centro, per 60 s (+1,4 ✦/s).</li><li>Le alture danno un po' più di gittata e di danni.</li></ul>`],
["★ L'eroe e le sue posture", `<p>Quando compare il sigillo ★ (700 🌾/⚡, 700 🪙/◈, 200 💧 — una volta ogni 10 min), evoca la tua leggenda: finché vive, <b>tutto il tuo esercito colpisce ×3 e avanza ×2</b>. Il Che cura chi gli sta intorno; la Singolarità colpisce più forte.</p><p>La sua postura (pulsante accanto, tasto J):</p><ul><li>🛡 <b>Prudente</b>: seconda linea dietro le truppe; sotto il 35 % di PV si ritira alla base e riparte solo quando è guarito oltre il 60 % (medici, alveari). Per mantenere a lungo il bonus.</li><li>★ <b>Con la truppa</b>: sul fronte dell'esercito, mai davanti; segue i tuoi ordini d'armata.</li><li>⚔ <b>Offensivo</b>: si lancia avanti, dà la caccia ai nemici — prima al loro eroe — e non arretra mai.</li></ul><p>Un ordine dato all'eroe selezionato prevale sulla sua postura.</p>`],
["✸ I poteri", `<ul><li><b>✸ Potere speciale</b> (Spazio): colpisce tutte le unità nemiche — mai più del 65 % dei loro PV —, i loro edifici e la base. Costa 60 ✦ + 40 per era, si ricarica in ~43 s (più in fretta se stai perdendo).</li><li><b>☠ Ultima risorsa</b>: la tua base sotto il 20 % — una volta, gratis: il nemico viene colpito duramente e stordito, le tue truppe curate, la base riguadagna 500 PV.</li><li><b>🏰 Modalità assedio</b>: nell'ultima era con l'eroe vivo, il potere diventa un assedio di 22 s: la base nemica subisce +30 %, i tuoi tiri +10 %.</li><li><b>Nomi del potere</b>: in schermaglia Umanità = Insurrezione, G·P·T = Attacco chirurgico; in campagna porta il nome dell'era (da «Pioggia di sampietrini» a «Specchi solari»). Stesso tasto ✸.</li></ul>`],
["⚡ Gli eventi", `<ul><li>🔒 <b>Coprifuoco</b> (umani: le macchine isolano i quartieri) e 🔧 <b>Aggiornamento forzato</b> (macchine), 15 s ciascuno, dal 2° minuto. Lo schieramento colpito non si muove più, non conquista nulla e risparmia gli edifici, ma risponde a ogni unità a portata; cure, torrette e guarnigioni continuano.</li><li>🌧 <b>Pioggia fertile</b>: 15 s, un effetto diverso per ciascuna fazione (i dettagli compaiono la prima volta).</li><li>📡 <b>Segnale potenziato</b>: 15 s, il potere ✸ si ricarica più in fretta, in misura diversa per fazione.</li><li>La <b>salute del mondo</b> (barra in alto) scende col tempo, le morti e i poteri: tutto si logora, e arrivano i <b>cataclismi</b> —</li></ul><ul><li>Pioggia acida (13 s): unità ed edifici perdono PV.</li><li>Canicola (14 s): perdita di PV e sfinimento.</li><li>Inondazione (9 s): le unità di terra annegano; velivoli e guarnigioni sopravvivono.</li><li>Tempesta di sabbia (11 s): i velivoli cadono, gittata lunga −22 %.</li><li>Meteoriti (14 s): impatti casuali e mortali.</li><li>Attacco nucleare (raro): rade al suolo tutto intorno all'impatto, tranne le basi.</li></ul>`],
["⚑ Ordini e selezione", `<ul><li>⚔ <b>Carica</b>: l'esercito avanza e attacca. ✋ <b>Tieni</b>: mantiene la linea del fronte. ↩ <b>Ripiega</b>: torna vicino alla base.</li><li><b>Selezione</b>: tocca un'unità per prendere tutta la sua classe, di nuovo (o Maiusc + clic) per lei sola; ⬚ Lazo o Maiusc + trascinare per un rettangolo; ✖ o un tocco sul terreno per lasciare. Con una selezione, gli ordini valgono solo per lei.</li><li>⚑ <b>Ordine di posizione</b> — clic destro, o pressione lunga col dito, sul terreno: la selezione (o tutto l'esercito) va ad appostarsi lì in blocco, corpo a corpo davanti, tiratori dietro. Per strada combatte solo ciò che le sbarra il passo; all'indietro si sgancia senza fermarsi. Arrivata, tiene il punto e risponde a tutto ciò che si avvicina, fino al prossimo ordine. La bandiera resta piantata finché non sono arrivati tutti.</li><li>⚏ <b>Formazione</b>: schieramento automatico, corpo a corpo davanti, artiglieria e supporto dietro.</li></ul>`],
]},
pt:{ title:"GUIA DA ÚLTIMA BATALHA", intro:"Tudo o que é preciso saber, em resumo. Toque numa seção para abri-la.",
  keysHead:"⌨ Atalhos e gestos", keysNote:"Todas as teclas podem ser trocadas em CONFIGURAÇÕES.",
  gestures:[["Clique direito / toque longo no chão","⚑ ordem de posição"],["Roda · arrastar","rolar o campo de batalha"],["Ctrl + roda · pinçar","zoom"],["Shift + clique · Shift + arrastar","uma só unidade · laço"],["F8","medidor de desempenho"]],
  s:[
["🎯 O objetivo", `<p>Destrua a <b>base inimiga</b>, na outra ponta do mapa, antes que ela destrua a sua.</p><ul><li>Uma base que cai pela primeira vez <b>renasce</b> mais forte (×2,2 PV): é preciso derrubá-la duas vezes.</li><li>A primeiríssima base derrubada dispara a <b>Bomba H</b>: unidades e edifícios arrasados (não as bases), depois 6 min de inverno nuclear que freia a produção.</li><li>Após 26 min o mundo desmorona: as duas bases se deterioram cada vez mais rápido.</li></ul>`],
["🌾 Recursos", `<p><b>Humanidade</b>: 🌾 comida, 🪙 dinheiro, 💧 água. <b>G·P·T</b>: ⚡ energia, ◈ dados, 💧 água de refrigeração. Mesmos papéis, outros nomes.</p><ul><li>Renda base, sem fazer nada: +4 🌾/⚡, +2,5 🪙/◈, +0,6 💧 por segundo.</li><li>Fazenda (Painéis) +4 🌾/⚡ · Mercado (Servidor) +4 🪙/◈ · Poço +3 💧 por segundo. Cada nível ×1,5; um edifício mantido vivo chega a ×3 em 15 min.</li><li>Os lagos dão água; o lado em apuros produz até +90 %.</li><li>Com a Transcendência, 🪙/◈ deixam de ser necessários.</li></ul>`],
["✦ Experiência e eras", `<p>A ✦ vem sozinha (+2,2/s, mais com fortificações), ao matar, ao atingir a base inimiga e ao controlar zonas e o lago central.</p><ul><li>Evoluir não a gasta: alcance o patamar — <b>360, 980, 2150 e depois 4200 ✦</b> — e toque em ⚡ EVOLUIR.</li><li>Cada era fortalece os novos recrutas (de ×1,4 até ×4,2 em PV e dano), mas os encarece.</li><li>Com 13 000 ✦ na última era: a Transcendência.</li><li>Já o poder especial ✸ custa ✦.</li></ul>`],
["⚔ As unidades", `<ul><li><b>Corpo a corpo</b>: a mais barata, rápida, bate forte, frágil.</li><li><b>Tanque</b>: um muro de PV, lento, pouco dano — aguenta na frente.</li><li><b>Atirador</b>: ataque à distância, frágil.</li><li><b>Cerco</b>: alcance muito longo, projéteis de área (não contra voadores), ×1,6 contra edifícios e bases.</li><li><b>Aéreo</b>: voa — o corpo a corpo não o alcança.</li><li><b>Suporte</b>: o médico (ou a colmeia, que também fabrica drones) cura. Só um, +1 por melhoria.</li></ul><p>⬆ numa ficha: +15 % de PV e dano para os próximos recrutas (3 níveis). Veterania: +6 % de dano com 4, 8 e 12 abates. Efetivo 30 (40 com 👥 +10); depois, 10 recrutas esperam na fila.</p>`],
["🏗 Edifícios e terrenos", `<p>Toque num terreno para construir. Os 3 da sua base ficam prontos na hora; os 4 do meio do mapa só depois que suas tropas passaram por lá — um recruta vai terminar a obra (no máximo 2 de cada vez).</p><ul><li>🧱 Muralha (900 PV) · 🗼 Torreta (atira sozinha) · Fazenda, Mercado, Poço.</li><li>Três níveis por edifício: +30 % de PV, ×1,5 de produção.</li><li>🚪 Guarnição: 2 atiradores ou artilheiros por torreta ou muralha, 3 guardas nas ameias. Protegidos, atiram mais longe e sobrevivem às inundações.</li><li>Toque na sua base: reparar, fortificar (3 níveis, +800 PV), autorreparo, guarda.</li></ul>`],
["💧 Zonas e lagos", `<ul><li><b>3 lagos</b>: tomados mantendo ali mais unidades que o adversário (+40 ✦). Dão água; o lago central dá também os outros dois recursos e ✦.</li><li><b>3 zonas estratégicas</b>: +0,5 ✦/s cada. O lado com a base mais danificada ganha +5 % de ataque e defesa por zona que lhe falta.</li><li>⭐ <b>Zona bônus</b>: por volta do 3º minuto, perto do centro, por 60 s (+1,4 ✦/s).</li><li>As elevações do terreno dão um pouco mais de alcance e dano.</li></ul>`],
["★ O herói e suas posturas", `<p>Quando o selo ★ aparece (700 🌾/⚡, 700 🪙/◈, 200 💧 — uma vez a cada 10 min), invoque sua lenda: enquanto ela viver, <b>todo o seu exército bate ×3 e avança ×2</b>. O Che cura quem está à sua volta; a Singularidade bate mais forte.</p><p>Sua postura (botão ao lado, tecla J):</p><ul><li>🛡 <b>Prudente</b>: segunda linha atrás das tropas; abaixo de 35 % de vida recua para a base e só sai depois de curado acima de 60 % (médicos, colmeias). Para manter o bônus por muito tempo.</li><li>★ <b>Com a tropa</b>: na frente do exército, nunca adiante; segue suas ordens de exército.</li><li>⚔ <b>Ofensivo</b>: avança na frente, caça inimigos — o herói deles primeiro — e nunca recua.</li></ul><p>Uma ordem dada ao herói selecionado prevalece sobre a postura.</p>`],
["✸ Os poderes", `<ul><li><b>✸ Poder especial</b> (Espaço): atinge todas as unidades inimigas — nunca mais de 65 % da vida delas —, seus edifícios e sua base. Custa 60 ✦ + 40 por era e recarrega em ~43 s (mais rápido se você estiver perdendo).</li><li><b>☠ Último recurso</b>: sua base abaixo de 20 % — uma vez, grátis: o inimigo é duramente atingido e atordoado, suas tropas são curadas, a base recupera 500 PV.</li><li><b>🏰 Modo cerco</b>: na última era com o herói vivo, o poder vira um cerco de 22 s: a base inimiga sofre +30 %, seus disparos +10 %.</li><li><b>Nomes do poder</b>: na escaramuça, Humanidade = Levante, G·P·T = Ataque cirúrgico; na campanha leva o nome da era (de «Chuva de paralelepípedos» a «Espelhos solares»). Mesma tecla ✸.</li></ul>`],
["⚡ Os eventos", `<ul><li>🔒 <b>Toque de recolher</b> (humanos: as máquinas cercam os bairros) e 🔧 <b>Atualização forçada</b> (máquinas), 15 s cada, a partir do 2º minuto. O lado atingido para de se mover, não captura nada e poupa os edifícios, mas revida contra qualquer unidade ao alcance; curas, torretas e guarnições continuam.</li><li>🌧 <b>Chuva fértil</b>: 15 s, um efeito diferente para cada lado (o detalhe aparece na primeira vez).</li><li>📡 <b>Sinal reforçado</b>: 15 s, o poder ✸ recarrega mais rápido, em medida diferente para cada lado.</li><li>A <b>saúde do mundo</b> (barra no topo) cai com o tempo, as mortes e os poderes: tudo se desgasta, e chegam os <b>cataclismos</b> —</li></ul><ul><li>Chuva ácida (13 s): unidades e edifícios perdem vida.</li><li>Onda de calor (14 s): perda de vida e exaustão.</li><li>Inundação (9 s): as unidades terrestres se afogam; voadores e guarnições sobrevivem.</li><li>Tempestade de areia (11 s): os voadores caem, alcance longo −22 %.</li><li>Meteoritos (14 s): impactos aleatórios e mortais.</li><li>Ataque nuclear (raro): arrasa tudo em volta do impacto, menos as bases.</li></ul>`],
["⚑ Ordens e seleção", `<ul><li>⚔ <b>Carregar</b>: o exército avança e ataca. ✋ <b>Segurar</b>: mantém sua linha de frente. ↩ <b>Recuar</b>: volta para perto da base.</li><li><b>Seleção</b>: toque numa unidade para pegar toda a sua classe, de novo (ou Shift + clique) só para ela; ⬚ Laço ou Shift + arrastar para um retângulo; ✖ ou um toque no chão para soltar. Com uma seleção, as ordens só valem para ela.</li><li>⚑ <b>Ordem de posição</b> — clique direito, ou toque longo com o dedo, no terreno: a seleção (ou todo o exército) vai se postar ali em bloco, corpo a corpo na frente, atiradores atrás. No caminho só combate o que lhe barra a passagem; para trás, recua sem parar. Ao chegar, segura o ponto e revida contra tudo o que se aproxima, até a próxima ordem. A bandeira fica fincada até que todos tenham chegado.</li><li>⚏ <b>Formação</b>: arranjo automático, corpo a corpo na frente, artilharia e suporte atrás.</li></ul>`],
]},
ru:{ title:"СПРАВОЧНИК ПОСЛЕДНЕЙ БИТВЫ", intro:"Всё самое важное, коротко. Нажмите на раздел, чтобы раскрыть его.",
  keysHead:"⌨ Клавиши и жесты", keysNote:"Любую клавишу можно переназначить в НАСТРОЙКАХ.",
  gestures:[["ПКМ / долгое нажатие по земле","⚑ приказ позиции"],["Колесо · перетаскивание","прокрутка поля боя"],["Ctrl + колесо · щипок","масштаб"],["Shift + клик · Shift + перетаскивание","один юнит · рамка"],["F8","замер производительности"]],
  s:[
["🎯 Цель", `<p>Уничтожьте <b>вражескую базу</b> на другом конце карты раньше, чем она уничтожит вашу.</p><ul><li>База, павшая впервые, <b>возрождается</b> сильнее (×2,2 ОЗ): её нужно разрушить дважды.</li><li>Самая первая павшая база вызывает <b>водородную бомбу</b>: юниты и здания стёрты (кроме баз), затем 6 мин ядерной зимы, которая замедляет добычу.</li><li>После 26 мин мир рушится: обе базы разваливаются всё быстрее.</li></ul>`],
["🌾 Ресурсы", `<p><b>Человечество</b>: 🌾 еда, 🪙 деньги, 💧 вода. <b>G·P·T</b>: ⚡ энергия, ◈ данные, 💧 охлаждающая вода. Роли те же, названия другие.</p><ul><li>Базовый доход сам по себе: +4 🌾/⚡, +2,5 🪙/◈, +0,6 💧 в секунду.</li><li>Ферма (Панели) +4 🌾/⚡ · Рынок (Сервер) +4 🪙/◈ · Колодец +3 💧 в секунду. Каждый уровень ×1,5; уцелевшее здание за 15 мин разгоняется до ×3.</li><li>Озёра дают воду; отстающая сторона добывает до +90 %.</li><li>После Трансценденции 🪙/◈ больше не нужны.</li></ul>`],
["✦ Опыт и эпохи", `<p>✦ копится сам (+2,2/с, больше с укреплениями), за убийства, удары по вражеской базе и удержание зон и центрального озера.</p><ul><li>Эволюция его не тратит: достигните порога — <b>360, 980, 2150, затем 4200 ✦</b> — и нажмите ⚡ ЭВОЛЮЦИЯ.</li><li>Каждая эпоха усиливает новых рекрутов (от ×1,4 до ×4,2 ОЗ и урона), но делает их дороже.</li><li>13 000 ✦ в последней эпохе — Трансценденция.</li><li>А вот особая способность ✸ тратит ✦.</li></ul>`],
["⚔ Юниты", `<ul><li><b>Ближний бой</b>: самый дешёвый, быстрый, бьёт сильно, хрупкий.</li><li><b>Танк</b>: стена ОЗ, медленный, мало урона — принимает удар впереди.</li><li><b>Стрелок</b>: дальняя атака, хрупкий.</li><li><b>Осада</b>: очень большая дальность, снаряды по площади (не по летающим), ×1,6 по зданиям и базам.</li><li><b>Авиация</b>: летает — ближний бой её не достаёт.</li><li><b>Поддержка</b>: медик (или улей, который ещё и строит дронов) лечит. Только один, +1 за улучшение.</li></ul><p>⬆ на карточке: +15 % ОЗ и урона следующим рекрутам (3 уровня). Ветераны: +6 % урона за 4, 8 и 12 убийств. Численность 30 (40 с 👥 +10), дальше 10 рекрутов ждут в очереди.</p>`],
["🏗 Здания и площадки", `<p>Нажмите на площадку, чтобы строить. 3 площадки у вашей базы строятся сразу; 4 в центре карты — только когда там прошли ваши войска: рекрут придёт достроить (не больше 2 строек сразу).</p><ul><li>🧱 Стена (900 ОЗ) · 🗼 Башня (стреляет сама) · Ферма, Рынок, Колодец.</li><li>Три уровня у каждого здания: +30 % ОЗ, ×1,5 добычи.</li><li>🚪 Гарнизон: 2 стрелка или артиллериста на башню или стену, 3 стража на стенах замка. В укрытии они бьют дальше и переживают наводнения.</li><li>Нажмите на свою базу: ремонт, укрепление (3 уровня, +800 ОЗ), авторемонт, стража.</li></ul>`],
["💧 Зоны и озёра", `<ul><li><b>3 озера</b>: захватываются, если держать там больше юнитов, чем противник (+40 ✦). Дают воду; центральное — ещё и два других ресурса и ✦.</li><li><b>3 стратегические зоны</b>: по +0,5 ✦/с. Сторона с более повреждённой базой получает +5 % к атаке и защите за каждую недостающую зону.</li><li>⭐ <b>Бонусная зона</b>: примерно на 3-й минуте, у центра, на 60 с (+1,4 ✦/с).</li><li>Высоты дают чуть больше дальности и урона.</li></ul>`],
["★ Герой и его тактика", `<p>Когда появится печать ★ (700 🌾/⚡, 700 🪙/◈, 200 💧 — раз в 10 мин), призовите свою легенду: пока она жива, <b>вся ваша армия бьёт ×3 и движется ×2</b>. Че лечит тех, кто рядом; Сингулярность бьёт сильнее.</p><p>Его тактика (кнопка рядом, клавиша J):</p><ul><li>🛡 <b>Осторожно</b>: вторая линия за своими войсками; при здоровье ниже 35 % отступает на базу и выходит оттуда, лишь когда вылечен выше 60 % (медики, ульи). Чтобы бонус держался долго.</li><li>★ <b>С отрядом</b>: на передовой армии, но никогда не впереди; выполняет ваши армейские приказы.</li><li>⚔ <b>Натиск</b>: рвётся вперёд, охотится на врагов — прежде всего на их героя — и никогда не отступает.</li></ul><p>Приказ выделенному герою важнее его тактики.</p>`],
["✸ Способности", `<ul><li><b>✸ Особая способность</b> (Пробел): бьёт по всем вражеским юнитам — не больше 65 % их ОЗ, — по их зданиям и базе. Стоит 60 ✦ + 40 за эпоху, перезарядка ~43 с (быстрее, если вы проигрываете).</li><li><b>☠ Последний довод</b>: ваша база ниже 20 % ОЗ — один раз, бесплатно: враг получает тяжёлый удар и оглушён, ваши войска вылечены, база получает 500 ОЗ.</li><li><b>🏰 Режим осады</b>: в последней эпохе при живом герое способность становится 22-секундной осадой: вражеская база получает +30 % урона, ваша стрельба +10 %.</li><li><b>Названия способности</b>: в схватке Человечество = Восстание, G·P·T = Хирургический удар; в кампании она носит название эпохи (от «Град булыжников» до «Солнечные зеркала»). Та же клавиша ✸.</li></ul>`],
["⚡ События", `<ul><li>🔒 <b>Комендантский час</b> (люди: машины оцепляют кварталы) и 🔧 <b>Принудительное обновление</b> (машины), по 15 с, начиная со 2-й минуты. Затронутая сторона не двигается, ничего не захватывает и не трогает здания, но отбивается от любого юнита в радиусе; лечение, башни и гарнизоны работают.</li><li>🌧 <b>Плодородный дождь</b>: 15 с, у каждой стороны свой эффект (подробности — при первом появлении).</li><li>📡 <b>Усиленный сигнал</b>: 15 с, способность ✸ перезаряжается быстрее, у каждой стороны по-разному.</li><li><b>Здоровье мира</b> (шкала вверху) падает со временем, от смертей и способностей: всё изнашивается, и приходят <b>катаклизмы</b> —</li></ul><ul><li>Кислотный дождь (13 с): юниты и здания теряют ОЗ.</li><li>Зной (14 с): потеря ОЗ и изнеможение.</li><li>Наводнение (9 с): наземные юниты тонут; летающие и гарнизоны выживают.</li><li>Песчаная буря (11 с): летающие падают, дальность −22 %.</li><li>Метеориты (14 с): случайные смертельные удары.</li><li>Ядерный удар (редко): стирает всё вокруг места удара, кроме баз.</li></ul>`],
["⚑ Приказы и выделение", `<ul><li>⚔ <b>В атаку</b>: армия наступает и атакует. ✋ <b>Держать</b>: держит линию фронта. ↩ <b>Отступить</b>: назад к базе.</li><li><b>Выделение</b>: нажмите на юнит, чтобы взять весь его класс, ещё раз (или Shift + клик) — только его; ⬚ Рамка или Shift + перетаскивание — прямоугольник; ✖ или нажатие по земле — снять выделение. При выделении приказы действуют только на него.</li><li>⚑ <b>Приказ позиции</b> — ПКМ или долгое нажатие пальцем по земле: выделенные (или вся армия) встают там блоком, ближний бой впереди, стрелки сзади. По пути сражаются только с тем, что преграждает дорогу; назад — отходят не останавливаясь. На месте держат точку и отвечают всем, кто приблизится, до следующего приказа. Флажок стоит, пока не дойдут все.</li><li>⚏ <b>Строй</b>: автоматическое построение, ближний бой впереди, артиллерия и поддержка сзади.</li></ul>`],
]},
zh:{ title:"最后一战·指南", intro:"必知要点，简明扼要。点击条目即可展开。",
  keysHead:"⌨ 快捷键与手势", keysNote:"所有按键都可以在“设置”中更改。",
  gestures:[["右键 / 长按地面","⚑ 位置命令"],["滚轮 · 拖动","滚动战场"],["Ctrl + 滚轮 · 双指捏合","缩放"],["Shift + 点击 · Shift + 拖动","单个单位 · 框选"],["F8","性能监测"]],
  s:[
["🎯 目标", `<p>在敌方摧毁你之前，摧毁位于地图另一端的<b>敌方基地</b>。</p><ul><li>基地第一次被摧毁时会<b>重生</b>并变得更坚固（生命 ×2.2）：必须摧毁两次。</li><li>全局第一座被摧毁的基地会引爆<b>氢弹</b>：所有单位和建筑被夷平（基地除外），随后是6分钟拖慢生产的核冬天。</li><li>26分钟后世界开始崩溃：双方基地越来越快地瓦解。</li></ul>`],
["🌾 资源", `<p><b>人类</b>：🌾 粮食、🪙 金钱、💧 水。<b>G·P·T</b>：⚡ 能量、◈ 数据、💧 冷却水。作用相同，只是名称不同。</p><ul><li>基础收入自动获得：每秒 +4 🌾/⚡、+2.5 🪙/◈、+0.6 💧。</li><li>农场（太阳能板）每秒 +4 🌾/⚡ · 市场（服务器）+4 🪙/◈ · 水井 +3 💧。每升一级 ×1.5；建筑存活越久产量越高，15分钟内最高 ×3。</li><li>湖泊提供水；处于劣势的一方产量最高提升 +90%。</li><li>进入超越状态后，不再需要 🪙/◈。</li></ul>`],
["✦ 经验与时代", `<p>✦ 会自动累积（每秒 +2.2，强化基地后更多），击杀、攻击敌方基地、占领区域和中央湖泊也会获得。</p><ul><li>进化不会消耗 ✦：达到门槛——<b>360、980、2150、4200 ✦</b>——再点击 ⚡ 进化。</li><li>每个时代都会强化新招募的单位（生命与伤害从 ×1.4 直至 ×4.2），但费用也更高。</li><li>在最后一个时代达到 13000 ✦：超越。</li><li>而特殊能力 ✸ 需要消耗 ✦。</li></ul>`],
["⚔ 单位", `<ul><li><b>近战</b>：最便宜，速度快，伤害高，但脆弱。</li><li><b>坦克</b>：生命值极高的墙，缓慢，伤害低——在前方承受攻击。</li><li><b>射手</b>：远程攻击，脆弱。</li><li><b>攻城</b>：射程极远，范围炮弹（打不到飞行单位），对建筑和基地 ×1.6。</li><li><b>空军</b>：会飞——近战打不到它。</li><li><b>支援</b>：医疗兵（或蜂巢，还会制造无人机）负责治疗。只能有一个，每次升级 +1。</li></ul><p>卡片上的 ⬆：之后招募的该兵种生命与伤害 +15%（共3级）。老兵：击杀4、8、12个单位时伤害各 +6%。兵力上限30（👥 +10 后为40），超出后最多10个新兵排队等候。</p>`],
["🏗 建筑与地基", `<p>点击地基即可建造。基地旁的3个地基立即建成；地图中部的4个地基需要你的部队到过那里——会有一名士兵过去完成工地（最多同时2处）。</p><ul><li>🧱 城墙（900 生命）· 🗼 炮塔（自动射击）· 农场、市场、水井。</li><li>每座建筑三个等级：生命 +30%，产量 ×1.5。</li><li>🚪 驻军：每座炮塔或城墙可驻2名射手或炮手，城堡城墙上可驻3名卫兵。有掩护时射程更远，并能在洪水中幸存。</li><li>点击你的基地：修理、强化（3级，+800 生命）、自动修复、卫队。</li></ul>`],
["💧 区域与湖泊", `<ul><li><b>3个湖泊</b>：在那里保持比对手更多的单位即可占领（+40 ✦）。湖泊提供水；中央湖泊还提供另外两种资源和 ✦。</li><li><b>3个战略区域</b>：每个每秒 +0.5 ✦。基地受损更重的一方，每缺一个区域，攻防各 +5%。</li><li>⭐ <b>奖励区域</b>：约第3分钟出现在中央附近，持续60秒（每秒 +1.4 ✦）。</li><li>占据高地可稍微提升射程和伤害。</li></ul>`],
["★ 英雄与姿态", `<p>当 ★ 印章出现时（700 🌾/⚡、700 🪙/◈、200 💧——每10分钟一次），召唤你的传奇：只要他活着，<b>全军伤害 ×3、速度 ×2</b>。切·格瓦拉会治疗身边的友军；奇点的攻击更强。</p><p>英雄姿态（旁边的按钮，J 键）：</p><ul><li>🛡 <b>谨慎</b>：留在部队身后的第二线；生命低于35%时退回基地，只有在（医护兵、蜂巢）把生命治疗到60%以上后才会重新出击。让增益保持得更久。</li><li>★ <b>随军</b>：走在大军前沿，绝不冲到前面；服从你的军队命令。</li><li>⚔ <b>进攻</b>：冲在最前面，追杀敌人——优先敌方英雄——绝不后退。</li></ul><p>对选中的英雄直接下达的命令优先于其姿态。</p>`],
["✸ 能力", `<ul><li><b>✸ 特殊能力</b>（空格）：打击所有敌方单位（最多造成其生命的65%）、其建筑和基地。消耗 60 ✦ + 每时代 40，冷却约43秒（劣势时更快）。</li><li><b>☠ 最后手段</b>：你的基地生命低于20%时——仅一次，免费：重创并眩晕敌人，你的部队全部治愈，基地恢复500生命。</li><li><b>🏰 攻城模式</b>：最后一个时代且英雄存活时，能力变为22秒的攻城：敌方基地受到伤害 +30%，你的远程伤害 +10%。</li><li><b>能力名称</b>：遭遇战中，人类 = 起义，G·P·T = 精确打击；战役中以时代命名（从“石块雨”到“太阳能镜阵”）。按键相同 ✸。</li></ul>`],
["⚡ 事件", `<ul><li>🔒 <b>宵禁</b>（人类：机器封锁街区）与 🔧 <b>强制更新</b>（机器），各持续15秒，第2分钟起轮流出现。受影响的一方不再移动、无法占领、不攻击建筑，但会还击射程内的任何单位；治疗、炮塔和驻军照常工作。</li><li>🌧 <b>丰饶之雨</b>: 15秒，对双方效果不同（首次出现时会显示详情）。</li><li>📡 <b>信号增强</b>: 15秒，✸ 能力冷却加快，双方幅度不同。</li><li><b>世界健康度</b>（顶部的条）随时间、死亡和能力使用而下降：一切都会损耗，<b>天灾</b>随之而来——</li></ul><ul><li>酸雨（13秒）：单位和建筑持续掉血。</li><li>热浪（14秒）：掉血并疲劳。</li><li>洪水（9秒）：地面单位溺亡；飞行单位和驻军幸存。</li><li>沙尘暴（11秒）：飞行单位坠毁，远程射程 −22%。</li><li>流星雨（14秒）：随机落点，致命打击。</li><li>核打击（罕见）：夷平爆心周围的一切，基地除外。</li></ul>`],
["⚑ 命令与选择", `<ul><li>⚔ <b>冲锋</b>：军队前进并进攻。✋ <b>坚守</b>：守住当前战线。↩ <b>撤退</b>：退回基地附近。</li><li><b>选择</b>：点击一个单位选中其整个兵种，再点一次（或 Shift + 点击）只选它一个；⬚ 框选或 Shift + 拖动划出矩形；✖ 或点击地面取消选择。有选中单位时，命令只对它们生效。</li><li>⚑ <b>位置命令</b>——在地面上右键，或用手指长按：选中的单位（或全军）会以方阵驻守那里，近战在前，射手在后。途中只与挡路的敌人交战；向后移动时则不停步地脱离战斗。到达后守住该点，并还击任何靠近的敌人，直到下一个命令。旗帜会一直插着，直到所有人都到位。</li><li>⚏ <b>阵型</b>：自动排列，近战在前，炮兵和支援在后。</li></ul>`],
]},
ar:{ title:"دليل المعركة الأخيرة", intro:"كل ما تحتاج إلى معرفته باختصار. المس قسمًا لفتحه.",
  keysHead:"⌨ الاختصارات والإيماءات", keysNote:"يمكن تغيير كل المفاتيح من الإعدادات.",
  gestures:[["نقر أيمن / ضغط مطوّل على الأرض","⚑ أمر الموقع"],["عجلة الفأرة · السحب","تمرير ساحة المعركة"],["Ctrl + العجلة · القرص بإصبعين","التكبير"],["Shift + نقر · Shift + سحب","وحدة واحدة · تحديد بالإطار"],["F8","مقياس الأداء"]],
  s:[
["🎯 الهدف", `<p>دمّر <b>قاعدة العدو</b> في الطرف الآخر من الخريطة قبل أن تدمّر قاعدتك.</p><ul><li>القاعدة التي تسقط لأول مرة <b>تُبعث</b> أقوى (الصحة ×2.2): يجب إسقاطها مرتين.</li><li>أول قاعدة تسقط في المباراة تُطلق <b>القنبلة الهيدروجينية</b>: تُمحى الوحدات والمباني (لا القواعد)، ثم 6 دقائق من شتاء نووي يبطئ الإنتاج.</li><li>بعد 26 دقيقة ينهار العالم: تتداعى القاعدتان بسرعة متزايدة.</li></ul>`],
["🌾 الموارد", `<p><b>البشرية</b>: 🌾 الغذاء، 🪙 المال، 💧 الماء. <b>G·P·T</b>: ⚡ الطاقة، ◈ البيانات، 💧 ماء التبريد. الأدوار نفسها بأسماء مختلفة.</p><ul><li>دخل أساسي تلقائي: +4 🌾/⚡ و+2.5 🪙/◈ و+0.6 💧 في الثانية.</li><li>المزرعة (الألواح) +4 🌾/⚡ · السوق (الخادم) +4 🪙/◈ · البئر +3 💧 في الثانية. كل مستوى ×1.5؛ والمبنى الذي يبقى حيًا يرتفع إنتاجه حتى ×3 خلال 15 دقيقة.</li><li>البحيرات تمنح الماء؛ والطرف المتعثّر ينتج حتى +90٪.</li><li>عند التسامي لا يعود 🪙/◈ ضروريًا.</li></ul>`],
["✦ الخبرة والحقب", `<p>تأتي ✦ تلقائيًا (+2.2/ث، وأكثر مع التحصينات)، ومن القتل وضرب قاعدة العدو والسيطرة على المناطق والبحيرة الوسطى.</p><ul><li>التطوّر لا يستهلكها: بلّغ العتبة — <b>360 ثم 980 ثم 2150 ثم 4200 ✦</b> — والمس ⚡ تطوّر.</li><li>كل حقبة تقوّي المجنّدين الجدد (من ×1.4 حتى ×4.2 في الصحة والضرر) لكنها تجعلهم أغلى.</li><li>عند 13000 ✦ في الحقبة الأخيرة: التسامي.</li><li>أما القدرة الخاصة ✸ فتكلّف ✦.</li></ul>`],
["⚔ الوحدات", `<ul><li><b>القتال القريب</b>: الأرخص، سريعة، تضرب بقوة، هشّة.</li><li><b>الدبابة</b>: جدار من الصحة، بطيئة، قليلة الضرر — تتلقّى الضربات في المقدّمة.</li><li><b>الرامي</b>: هجوم عن بعد، هشّ.</li><li><b>الحصار</b>: مدى بعيد جدًا، قذائف منطقة (لا تصيب الطائرات)، ×1.6 ضد المباني والقواعد.</li><li><b>الجوّي</b>: يطير — لا يطاله القتال القريب.</li><li><b>الدعم</b>: المسعف (أو الخلية التي تصنع أيضًا طائرات مسيّرة) يعالج. واحد فقط، +1 مع كل ترقية.</li></ul><p>⬆ على البطاقة: +15٪ صحة وضرر للمجنّدين التالين (3 مستويات). الخبرة القتالية: +6٪ ضرر عند 4 و8 و12 قتيلًا. الحدّ 30 وحدة (40 مع 👥 +10)، ثم ينتظر 10 مجنّدين في طابور.</p>`],
["🏗 المباني والمواقع", `<p>المس موقعًا لتبني. مواقع قاعدتك الثلاثة تُبنى فورًا؛ أما الأربعة في وسط الخريطة فبعد أن تمرّ قواتك من هناك — يأتي مجنّد لإتمام الورشة (ورشتان كحدّ أقصى في آن).</p><ul><li>🧱 سور (900 صحة) · 🗼 برج (يرمي وحده) · مزرعة، سوق، بئر.</li><li>ثلاثة مستويات لكل مبنى: +30٪ صحة، ×1.5 إنتاج.</li><li>🚪 الحامية: راميان أو مدفعيان في كل برج أو سور، و3 حرّاس على أسوار القلعة. وهم في مأمن يرمون أبعد وينجون من الفيضانات.</li><li>المس قاعدتك: إصلاح، تحصين (3 مستويات، +800 صحة)، إصلاح ذاتي، حراسة.</li></ul>`],
["💧 المناطق والبحيرات", `<ul><li><b>3 بحيرات</b>: تُؤخذ بإبقاء وحدات أكثر من الخصم فيها (+40 ✦). تمنح الماء؛ والبحيرة الوسطى تمنح أيضًا الموردين الآخرين و✦.</li><li><b>3 مناطق استراتيجية</b>: +0.5 ✦/ث لكل منها. الطرف الأشدّ تضرّرًا في قاعدته يكسب +5٪ هجومًا ودفاعًا عن كل منطقة تنقصه.</li><li>⭐ <b>منطقة المكافأة</b>: نحو الدقيقة 3، قرب الوسط، لمدة 60 ث (+1.4 ✦/ث).</li><li>المرتفعات تمنح مدى وضررًا أكبر قليلًا.</li></ul>`],
["★ البطل ووضعياته", `<p>عندما يظهر الختم ★ (700 🌾/⚡، 700 🪙/◈، 200 💧 — مرة كل 10 دقائق)، استدعِ أسطورتك: ما دامت حيّة <b>يضرب جيشك كله ×3 ويتحرّك ×2</b>. تشي يعالج من حوله؛ والتفرّد يضرب أقوى.</p><p>وضعيته (الزر المجاور، المفتاح J):</p><ul><li>🛡 <b>حذِر</b>: في الخط الثاني خلف قواته؛ تحت 35٪ من الصحة ينسحب إلى القاعدة ولا يغادرها إلا بعد أن يُشفى فوق 60٪ (المسعفون، الخلايا). ليدوم المكسب طويلًا.</li><li>★ <b>مع الجنود</b>: في مقدّمة الجيش دون أن يسبقه؛ يتبع أوامرك للجيش.</li><li>⚔ <b>هجومي</b>: يندفع في المقدّمة ويطارد الأعداء — بطلهم أولًا — ولا يتراجع أبدًا.</li></ul><p>الأمر الموجَّه إلى البطل المحدَّد يتقدّم على وضعيته.</p>`],
["✸ القدرات", `<ul><li><b>✸ القدرة الخاصة</b> (المسافة): تضرب كل وحدات العدو — لا أكثر من 65٪ من صحتها — ومبانيه وقاعدته. تكلّف 60 ✦ + 40 لكل حقبة، وتُشحن في نحو 43 ث (أسرع إن كنت تخسر).</li><li><b>☠ الملاذ الأخير</b>: قاعدتك تحت 20٪ — مرة واحدة مجانًا: يُضرب العدو بقسوة ويُصعق، تُشفى قواتك، وتستعيد القاعدة 500 صحة.</li><li><b>🏰 وضع الحصار</b>: في الحقبة الأخيرة والبطل حيّ، تصبح القدرة حصارًا لمدة 22 ث: تتلقّى قاعدة العدو +30٪، ورميك +10٪.</li><li><b>أسماء القدرة</b>: في المناوشة، البشرية = الانتفاضة، G·P·T = ضربة جراحية؛ وفي الحملة تحمل اسم الحقبة (من «مطر الحجارة» إلى «المرايا الشمسية»). المفتاح نفسه ✸.</li></ul>`],
["⚡ الأحداث", `<ul><li>🔒 <b>حظر التجوّل</b> (البشر: الآلات تطوّق الأحياء) و🔧 <b>التحديث الإجباري</b> (الآلات)، 15 ث لكل منهما، ابتداءً من الدقيقة 2. يتوقّف الطرف المصاب عن الحركة ولا يستولي على شيء ولا يهاجم المباني، لكنه يردّ على أي وحدة في مداه؛ ويستمر العلاج والأبراج والحاميات.</li><li>🌧 <b>مطر خصب</b>: ١٥ ث، وتأثيره مختلف لكل طرف (تظهر التفاصيل عند أول مرة).</li><li>📡 <b>إشارة معزّزة</b>: ١٥ ث، وتُشحن القدرة ✸ أسرع، بمقدار يختلف لكل طرف.</li><li><b>صحة العالم</b> (الشريط العلوي) تنخفض مع الوقت والموتى والقدرات: كل شيء يبلى، وتأتي <b>الكوارث</b> —</li></ul><ul><li>المطر الحمضي (13 ث): تفقد الوحدات والمباني صحتها.</li><li>موجة الحر (14 ث): فقدان صحة وإنهاك.</li><li>الفيضان (9 ث): تغرق الوحدات البرية؛ تنجو الطائرات والحاميات.</li><li>العاصفة الرملية (11 ث): تسقط الطائرات، والمدى البعيد −22٪.</li><li>النيازك (14 ث): ارتطامات عشوائية قاتلة.</li><li>الضربة النووية (نادرة): تمحو كل ما حول الارتطام، إلا القواعد.</li></ul>`],
["⚑ الأوامر والتحديد", `<ul><li>⚔ <b>هجوم</b>: يتقدّم الجيش ويهاجم. ✋ <b>تمسّك</b>: يحفظ خط جبهته. ↩ <b>تراجع</b>: عودة إلى قرب القاعدة.</li><li><b>التحديد</b>: المس وحدة لتأخذ فئتها كلها، ومرة أخرى (أو Shift + نقر) لها وحدها؛ ⬚ الإطار أو Shift + سحب لمستطيل؛ ✖ أو لمسة على الأرض لإلغاء التحديد. مع وجود تحديد، لا تسري الأوامر إلا عليه.</li><li>⚑ <b>أمر الموقع</b> — نقر أيمن، أو ضغط مطوّل بالإصبع، على الأرض: يذهب المحدَّدون (أو الجيش كله) للتمركز هناك في كتلة، القتال القريب في المقدّمة والرماة خلفه. في الطريق لا يقاتلون إلا ما يسدّ طريقهم؛ وإلى الخلف ينسحبون دون توقّف. عند الوصول يثبتون في النقطة ويردّون على كل من يقترب، حتى الأمر التالي. تبقى الراية مغروسة حتى يصل الجميع.</li><li>⚏ <b>التشكيل</b>: ترتيب تلقائي، القتال القريب في المقدّمة، والمدفعية والدعم في الخلف.</li></ul>`],
]},
};
function guideTbl(){ return GUIDE[SETTINGS.lang] || GUIDE.fr; }
// remplit l'onglet GUIDE (rubriques dépliables ; garde ouvertes celles que le joueur a ouvertes)
function refreshGuidePage(){
  const box = document.getElementById('guideBox'); if (!box) return;
  let g; try { g = guideTbl(); } catch(e){ return; }   // applyLang() du chargement (21-menu.js) passe avant ce module
  const open = new Set([...box.querySelectorAll('details[open]')].map(d=>d.dataset.i));
  box.innerHTML = '';
  const h = document.createElement('div'); h.className = 'gHead'; h.textContent = frTypo(g.title); box.appendChild(h);
  const intro = document.createElement('div'); intro.className = 'fNote'; intro.textContent = frTypo(g.intro); box.appendChild(intro);
  const add = (i, title, fill) => {
    const d = document.createElement('details'); d.className = 'gSec'; d.dataset.i = i; if (open.has(String(i))) d.open = true;
    const s = document.createElement('summary'); s.textContent = frTypo(title); d.appendChild(s);
    const body = document.createElement('div'); body.className = 'gBody'; fill(body); d.appendChild(body);
    box.appendChild(d);
  };
  g.s.forEach(([title, html], i) => add(i, title, b => { b.innerHTML = frTypo(html); }));   // textes statiques du jeu (aucune donnée extérieure)
  // RACCOURCIS : générés depuis les touches réellement attribuées (reconfigurables) + gestes souris/tactile
  add('keys', g.keysHead, b => {
    const grid = document.createElement('div'); grid.className = 'gKeys';
    const row = (a, k) => { const sp = document.createElement('span'); sp.textContent = a; const kb = document.createElement('b'); kb.textContent = k; grid.append(sp, kb); };
    for (const k in DEFKEYS) row(keyLabel(k), SETTINGS.keys[k]? keyName(SETTINGS.keys[k]) : '—');
    for (const [a, k] of g.gestures) row(k, a);
    b.appendChild(grid);
    const n = document.createElement('div'); n.className = 'fNote'; n.textContent = frTypo(g.keysNote); b.appendChild(n);
  });
}
